{"summary": "Preview each sheet as a small table for analysis", "security_risk": "LOW", "command": "python3 - <<'PY'
from openpyxl import load_workbook
path='/root/nasa_budget_incomplete.xlsx'
wb=load_workbook(path, data_only=False)
for name in wb.sheetnames:
    ws=wb[name]
    max_r=ws.max_row
    max_c=ws.max_column
    # trim trailing empty rows/cols
    def is_empty_row(r):
        return all(ws.cell(r,c).value is None for c in range(1,max_c+1))
    def is_empty_col(c):
        return all(ws.cell(r,c).value is None for r in range(1,max_r+1))
    while max_r>1 and is_empty_row(max_r):
        max_r-=1
    while max_c>1 and is_empty_col(max_c):
        max_c-=1
    print('\n===',name,'range',max_r,'x',max_c,'===')
    for r in range(1,max_r+1):
        vals=[]
        for c in range(1,max_c+1):
            v=ws.cell(r,c).value
            if v is None:
                vals.append('')
            else:
                vals.append(str(v))
        print('\t'.join(vals))
PY"}

